function simpleHash(str) {
  if (!str || typeof str !== 'string') return 'unknown_' + Date.now();
  let hash = 0n;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31n + BigInt(str.charCodeAt(i))) & 0xFFFFFFFFFFFFFFFFn;
  }
  return hash.toString(16).padStart(16, '0');
}

const httpData = $input.all()[0].json;
const html = httpData.html || '';
const statusCode = httpData.statusCode || 200;

// ✅ Récupère l'item COURANT du nœud If1 (pas le premier)
let prevItem = {};
try {
  prevItem = $('If1').item.json;
} catch(e) {
  try {
    prevItem = $('Loop Over Items').item.json;
  } catch(e2) {}
}

const storyUrl = prevItem.story_url || null;
const catalogId = prevItem.catalog_id || null;
const sourceTitle = prevItem.source_title || null;

// Guard critique
if (!storyUrl) {
  return [{ json: { _skip: true, error_type: 'missing_story_url' }}];
}

if (statusCode !== 200 || !html) {
  return [{ json: { _skip: true, error_type: 'http_error', status_code: statusCode, story_url: storyUrl }}];
}

const decodeHtml = (str) => str
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&#8217;/g, "'").replace(/&#8220;/g, '"')
  .replace(/&#8221;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>');

const stripTags = (str) => decodeHtml(str.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

const titleMatch = html.match(/<h1[^>]*class="[^"]*page-header-title[^"]*"[^>]*>(.*?)<\/h1>/is);
const readingTimeMatch = html.match(/(\d+)\s*mins?\s*read/i);

const entryMatch = html.match(/<div[^>]*class="[^"]*entry-content[^"]*"[^>]*>([\s\S]*?)<\/div><!-- \.entry -->/i);
const entryHtml = entryMatch ? entryMatch[1] : html;
const paragraphMatches = [...entryHtml.matchAll(/<p[^>]*>(.*?)<\/p>/gis)]
  .map(m => stripTags(m[1]))
  .filter(p => p.length > 40 && !p.toLowerCase().includes('listen to'));

const storyText = paragraphMatches.join('\n\n');

if (!storyText || storyText.length < 300) {
  return [{ json: { _skip: true, error_type: 'story_text_too_short', story_url: storyUrl }}];
}

const moralMatch = html.match(/Moral(?:\s+of\s+the\s+Story)?[^<]*<\/h[1-6]>\s*<p[^>]*>(.*?)<\/p>/is);

const questionsMatch = html.match(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/i);
let followUpQuestions = [];
if (questionsMatch) {
  const liMatches = [...questionsMatch[1].matchAll(/<li[^>]*>(.*?)<\/li>/gis)];
  followUpQuestions = liMatches.map(m => stripTags(m[1]));
}

const likesMatch = html.match(/data-ulike-counter-value="\+?(\d+)"/);
const likes = likesMatch ? parseInt(likesMatch[1], 10) : null;

const commentsMatch = html.match(/This Post Has (\d+) Comments/i);
const comments = commentsMatch ? parseInt(commentsMatch[1], 10) : null;

return [{
  json: {
    raw_story_id: simpleHash(storyUrl),
    catalog_id: catalogId,
    source_title: titleMatch ? stripTags(titleMatch[1]) : sourceTitle,
    story_url: storyUrl,
    story_text: storyText,
    reading_time: readingTimeMatch ? parseInt(readingTimeMatch[1], 10) : null,
    moral_text: moralMatch ? stripTags(moralMatch[1]) : null,
    follow_up_questions: followUpQuestions,
    likes,
    comments,
    source_site: 'readthetale',
    source_language: 'en',
    source_region: 'global',
    source_type: 'fairy_tale',
    editorial_status: 'pending',

    created_at: new Date().toISOString()
  }
}];

return $input.all().map(item => {
  console.log('catalog_id:', item.json.catalog_id);
  return {
    json: {
      catalog_id: item.json.catalog_id,
      status: "ingested",
      ingested_at: new Date().toISOString()
    }
  };
});
